inputs.text:
$=
	string originText = {text};

// 合并JArray文本串
Func<JArray, string, string> JoinArray = (JArray JArray, string splitter) =>
{
	if (JArray != null)
	{
		return String.Join(splitter, JArray.Select(x => (string)x));
	}

	return "";
};


var jToken = JToken.Parse({rawData}) as JObject;

// 构造结果
StringBuilder sb = new StringBuilder();


sb.AppendLine(originText);
//sb.AppendLine("----");
sb.AppendLine();

//基础翻译结果
var translation = jToken["translation"] as JArray;
if (translation != null)
{
	sb.AppendLine("【翻译结果】");
	foreach (var item in translation)
	{
		sb.AppendLine(item.ToString());
	}
	sb.AppendLine();
}

// 单词内容
var isWord = jToken.Value<bool?>("isWord") == true;
var basic = jToken["basic"] as JObject;
if (isWord && basic != null)
{


	if (basic.ContainsKey("phonetic"))
	{
		sb.AppendLine("【单词发音】");
		sb.Append($"{basic.Value<string>("phonetic")} ");
		if (basic.ContainsKey("us-phonetic")){
			sb.Append($"[美]{basic.Value<string>("us-phonetic")} ");
		}
		if (basic.ContainsKey("uk-phonetic")){
			sb.Append($"[英]{basic.Value<string>("uk-phonetic")} ");
		}
		
		sb.AppendLine();
		sb.AppendLine();
	}

	//基本释义
	var explains = basic["explains"] as JArray;
	if (explains != null)
	{
		sb.AppendLine("【基本释义】");
		foreach (var exp in explains)
		{
			sb.AppendLine(exp.ToString());
		}
		sb.AppendLine();
	}

	// 变换
	var wfs = basic["wfs"] as JArray;
	if (wfs != null)
	{
		sb.AppendLine("【词形变换】");
		foreach (var wf in wfs)
		{
			sb.Append($"{wf["wf"].Value<string>("name")}: {wf["wf"].Value<string>("value")};  ");
		}
		sb.AppendLine();
		sb.AppendLine();
	}

	var exam_type = basic["exam_type"] as JArray;
	if (exam_type != null)
	{
		sb.AppendLine("【考试范围】");
		foreach (var item in exam_type)
		{
			sb.Append(item.ToString());
			sb.Append("; ");
		}
		sb.AppendLine();
		sb.AppendLine();
	}
}

// 网络释义
var web = jToken["web"] as JArray;
if (web != null)
{
	sb.AppendLine("【网络释义】");
	foreach (var item in web)
	{
		//sb.AppendLine(item.ToString());
		sb.Append(item.Value<string>("key"));
		sb.Append(": ");
		sb.Append(JoinArray(item.Value<JArray>("value"), " | "));
		
		sb.AppendLine();
	}
	sb.AppendLine();
}

var dictLink = jToken["webdict"]?.Value<string>("url");
if (dictLink != null)
{
	sb.AppendLine("【网络词典链接】");
	sb.AppendLine($"{dictLink}");
}

return sb.ToString();
